<div><label for="f-loss">Type of loss</label><select id="f-loss" name="loss"><option>Ice dam / frozen pipe</option><option>Water / leak</option><option>Wind / microburst</option><option>Hail / roof</option><option>Snow load / collapse</option><option>Fire / smoke</option><option>Tropical storm</option><option>Fallen tree</option><option>Other</option></select></div>
<div><label for="f-city">Property location</label><select id="f-city" name="city"><option>Burlington</option><option>South Burlington</option><option>Rutland</option><option>Montpelier</option><option>Barre</option><option>St. Albans</option><option>Brattleboro</option><option>Bennington</option><option>Middlebury</option><option>St. Johnsbury</option><option>Stowe</option><option>Hartford</option><option>Elsewhere in Vermont</option></select></div>
<div><label for="f-amt">Approx. amount in dispute</label><select id="f-amt" name="amount"><option>Not sure</option><option>Under $10,000</option><option>$10,000–$25,000</option><option>$25,000–$75,000</option><option>$75,000–$250,000</option><option>Over $250,000</option></select></div>
<div class="full"><label for="f-car">Insurance company (optional)</label><input id="f-car" name="carrier"></div>
<div class="full"><label for="f-det">What happened, and where does the claim stand?</label><textarea id="f-det" name="details" placeholder="Date of loss, what the carrier paid or offered, and what you think was missed."></textarea></div>
<div class="full hp" aria-hidden="true"><label for="f-web">Website</label><input id="f-web" name="website" tabindex="-1" autocomplete="off"></div>
<input type="hidden" name="page" value="/claim-review-request/">
